struct Child {
    int v, d, p, idx;
};

int main() {
    int n;
    cin >> n;
    queue<Child> q;
    for (int i = 0; i < n; ++i) {
        int v, d, p;
        cin >> v >> d >> p;
        q.push({v, d, p, i+1});
    }

    vector<int> result;

    while (!q.empty()) {
        Child current = q.front();
        q.pop();
        result.push_back(current.idx);

        int v = current.v;
        vector<Child> temp;
        queue<Child> newQueue;

        // Subtract vi - (k-1) from the first vi children
        int k = 0;
        while (!q.empty() && k < v) {
            Child c = q.front();
            q.pop();
            c.p -= (v - k);
            temp.push_back(c);
            k++;
        }

        // Add remaining children without modification
        while (!q.empty()) {
            temp.push_back(q.front());
            q.pop();
        }

        // Now process potential cries due to dj
        bool changed;
        do {
            changed = false;
            vector<Child> newTemp;
            int dj = 0;
            for (auto& c : temp) {
                c.p -= dj;
                if (c.p >= 0) {
                    newTemp.push_back(c);
                } else {
                    dj += c.d;
                    changed = true;
                }
            }
            temp.swap(newTemp);
        } while (changed);

        // Rebuild the queue
        for (auto& c : temp) {
            newQueue.push(c);
        }
        q = newQueue;
    }

    cout << result.size() << endl;
    for (int num : result) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
