using namespace std;

const int MOD = 1e9 + 7;

long long pow_mod(long long a, long long b, int mod) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

int main() {
    int p, k;
    cin >> p >> k;
    if (k == 0) {
        cout << pow_mod(p, p-1, MOD) << endl;
    } else if (k == 1) {
        cout << pow_mod(p, p, MOD) << endl;
