    bool operator<(const Event& other) const {
        return pos < other.pos;
    }
};

long long calculate_covered(const vector<Segment>& segs, bool is_horizontal) {
    vector<Event> events;
    for (const auto& seg : segs) {
        if (seg.is_horizontal() == is_horizontal) {
            if (is_horizontal) {
                events.push_back({seg.y1, seg.x1, seg.x2, 1});
            } else {
                events.push_back({seg.x1, seg.y1, seg.y2, 1});
            }
        }
    }
    if (events.empty()) return 0;

    sort(events.begin(), events.end());

    long long total = 0;
    multiset<pair<int, int>> active;
    int current_pos = events[0].pos;

    for (size_t i = 0; i < events.size(); ) {
        int pos = events[i].pos;
        if (current_pos != pos) {
            current_pos = pos;
        }

        while (i < events.size() && events[i].pos == pos) {
            auto [s, e] = minmax(events[i].start, events[i].end);
            active.insert({s, e});
            i++;
        }

        int last = INT_MIN;
        int cnt = 0;
