#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct NumInfo {
    bool isBeautiful;
    int zeros;
};

NumInfo checkBeautiful(const string& s) {
    NumInfo info;
    info.isBeautiful = true;
    info.zeros = 0;
    int ones = 0;
    for (char c : s) {
        if (c != '0' && c != '1') {
            info.isBeautiful = false;
        }
        if (c == '1') {
            ones++;
            if (ones > 1) {
                info.isBeautiful = false;
            }
        } else if (c == '0') {
            info.zeros++;
        }
    }
    if (ones == 0 && s.size() > 1) {
        info.isBeautiful = false;
    }
    return info;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<NumInfo> nums(n);
    string nonSpecial = "1";
    int totalZeros = 0;
    bool hasZero = false;

    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;

        if (s == "0") {
            hasZero = true;
        }

        NumInfo info = checkBeautiful(s);
        nums[i] = info;

        if (info.isBeautiful) {
            totalZeros += info.zeros;
        } else {
            nonSpecial = s;
        }
    }

    if (hasZero) {
        cout << "0\n";
        return 0;
    }

    string result = nonSpecial;
    for (int i = 0; i < totalZeros; i++) {
        result += '0';
    }

    cout << result << '\n';
    return 0;
}

