using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int min_pos = find(a.begin(), a.end(), 1) - a.begin();
    int max_pos = find(a.begin(), a.end(), n) - a.begin();
    int original_dist = abs(max_pos - min_pos);
    int best_dist = original_dist;

    // Try swapping each element with both min and max to see if we can get a better distance
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            // Swap i and j
            swap(a[i], a[j]);

            // Find new positions of min and max after swap
            int new_min = find(a.begin(), a.end(), 1) - a.begin();
            int new_max = find(a.begin(), a.end(), n) - a.begin();
            int current_dist = abs(new_max - new_min);
            if (current_dist > best_dist) {
                best_dist = current_dist;
            }

            // Swap back
            swap(a[i], a[j]);
        }
    }

    cout << best_dist << endl;
    return 0;
}

