using ll = long long;
const ll INF = 1e18;

struct Edge {
    int u, v;
    ll w;
    bool original;
};

vector<Edge> edges;
int n, m, s, t;
ll L;

vector<ll> dijkstra(const vector<vector<pair<int, ll>>>& adj, int start) {
    vector<ll> dist(n, INF);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    dist[start] = 0;
    pq.emplace(0, start);
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto& [v, w] : adj[u]) {
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.emplace(dist[v], v);
            }
        }
    }
    return dist;
}

vector<vector<pair<int, ll>>> build_adj(bool use_one) {
    vector<vector<pair<int, ll>>> adj(n);
    for (auto& e : edges) {
        ll w = e.w;
