#include <vector>
#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    vector<int> visited(n, 0);
    int result = 0;

    for (int i = 0; i < n; ++i) {
        if (visited[i]) continue;

        vector<int> path;
        int current = i;
        bool cycle = false;

        while (true) {
            if (current < 0 || current >= n) {
                // Falls off, mark all in path and add to result
                for (int pos : path) {
                    visited[pos] = 1;
                }
                result += path.size();
                break;
            }

            if (visited[current]) {
                if (visited[current] == 1) {
                    // Already processed and falls off
                    break;
                } else {
                    // Cycle detected, mark as part of cycle
                    cycle = true;
                    break;
                }
            }

            // Mark as being visited (2)
            visited[current] = 2;
            path.push_back(current);

            if (s[current] == '>') {
                current++;
            } else {
                current--;
            }
        }

        if (cycle) {
            for (int pos : path) {
                if (visited[pos] == 2) {
                    visited[pos] = 3;
                }
            }
        } else {
            for (int pos : path) {
                visited[pos] = 1;
            }
        }
    }

    cout << result << '\n';

    return 0;
}

