#include <bits/stdc++.h>
using namespace std;

const int MAXN = 105;
int crush[MAXN];
bool visited[MAXN];
int component[MAXN], comp_size[MAXN], comp_id = 0;
int cycle_length[MAXN];

void dfs(int u, int comp) {
    if (visited[u]) return;
    visited[u] = true;
    component[u] = comp;
    comp_size[comp]++;
    dfs(crush[u], comp);
}

int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> crush[i];
    }

    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            comp_id++;
            comp_size[comp_id] = 0;
            dfs(i, comp_id);
        }
    }

    bool possible = true;
    for (int i = 1; i <= n; ++i) {
        int current = i;
        unordered_set<int> seen;
        while (seen.find(current) == seen.end()) {
            seen.insert(current);
            current = crush[current];
        }
        if (crush[current] != current && seen.count(crush[current])) {
            possible = false;
            break;
        }
    }

    if (!possible) {
        cout << -1 << endl;
        return 0;
    }

    for (int i = 1; i <= comp_id; ++i) {
        cycle_length[i] = 0;
    }

    for (int i = 1; i <= n; ++i) {
        if (component[i] == 0) continue;
        int len = 0;
        int current = i;
        unordered_set<int> seen;
        while (seen.find(current) == seen.end()) {
            seen.insert(current);
            current = crush[current];
            len++;
        }
        if (current == i) {
            cycle_length[component[i]] = len;
            component[i] = 0;
            for (auto x : seen) component[x] = 0;
        }
    }

    long long ans = 1;
    for (int i = 1; i <= comp_id; ++i) {
        if (cycle_length[i] == 0) {
            possible = false;
            break;
        }
        if (cycle_length[i] % 2 == 0) {
            ans = lcm(ans, cycle_length[i] / 2);
        } else {
            ans = lcm(ans, cycle_length[i]);
        }
    }

    if (!possible) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }

    return 0;
}

