using namespace std;
using ll = long long;

int main() {
    ll n, m, k, x, y;
    cin >> n >> m >> k >> x >> y;

    ll period = 0;
    if (n == 1) {
        period = m;
    } else {
        period = (2 * (n - 1) * m);
    }

    ll full_cycles = 0;
    ll remaining = k;
    if (period > 0) {
        full_cycles = k / period;
        remaining = k % period;
    }

    vector<vector<ll>> counts(n + 1, vector<ll>(m + 1, 0));

    for (ll i = 1; i <= n; ++i) {
        for (ll j = 1; j <= m; ++j) {
            if (n == 1) {
                counts[i][j] = full_cycles;
            } else {
                if (i == 1 || i == n) {
                    counts[i][j] = full_cycles;
                } else {
                    counts[i][j] = 2 * full_cycles;
                }
            }
        }
    }

    ll current_row = 1;
    ll direction = 1;

    while (remaining > 0) {
        for (ll j = 1; j <= m; ++j) {
            if (remaining == 0) break;
            counts[current_row][j]++;
            remaining--;
        }
        if (current_row + direction < 1 || current_row + direction > n) {
            direction *= -1;
        }
        current_row += direction;
    }

    ll max_count = 0, min_count = LLONG_MAX;
    for (ll i = 1; i <= n; ++i) {
