vector<Option> findOptions(int M) {
    vector<Option> res;
    for (int x = 1; x <= K; ++x) {
        if (rowFilled[x]) continue;
        auto& s = seats[x];
        int prevEnd = 0;
        for (auto& p : s) {
            int start = prevEnd + 1;
            int end = p.first - 1;
            if (end - start + 1 >= M) {
                for (int yl = start; yl <= end - M + 1; ++yl) {
                    res.emplace_back(x, yl, yl + M - 1);
                }
            }
            prevEnd = p.second;
        }
        int start = prevEnd + 1;
        int end = K;
        if (end - start + 1 >= M) {
            for (int yl = start; yl <= end - M + 1; ++yl) {
                res.emplace_back(x, yl, yl + M - 1);
            }
        }
    }
    if (res.empty()) return {};
    sort(res.begin(), res.end());
    return {res[0]};
