void bookSeats(int x, int yl, int yr) {
    auto& s = seats[x];
    auto it = s.lower_bound({yl, 0});
    if (it != s.begin()) --it;
    vector<pair<int, int>> toErase;
    pair<int, int> newSeg = {yl, yr};
