using namespace std;

int K, center_row, center_seat;
vector<set<pair<int, int>>> seats; 

int distance(int x, int y) {
    return (x - center_row) * (x - center_row) + (y - center_seat) * (y - center_seat);
}

tuple<int, int, int, int> find_best(int M) {
    tuple<int, int, int, int> best = {INT_MAX, INT_MAX, INT_MAX, INT_MAX};

    for (int x = 1; x <= K; ++x) {
        auto& occupied = seats[x-1];
        if (occupied.empty()) {
            int start = 1;
            int end = start + M -1;
            if (end > K) continue;
            int total = 0;
            for (int y = start; y <= end; ++y) {
                total += distance(x, y);
            }
            tuple<int, int, int, int> current = {total, x, start, end};
            if (current < best) best = current;
            continue;
        }

        vector<pair<int, int>> intervals;
        int prev_end = 0;
        for (auto& p : occupied) {
            int start = prev_end + 1;
            int end = p.first - 1;
            if (start <= end) {
                intervals.emplace_back(start, end);
            }
            prev_end = p.second;
        }
        int start = prev_end + 1;
        int end = K;
        if (start <= end) {
            intervals.emplace_back(start, end);
        }

        for (auto& interval : intervals) {
            int s = interval.first;
            int e = interval.second;
            if (e - s + 1 < M) continue;
            for (int yl = s; yl <= e - M + 1; ++yl) {
                int yr = yl + M - 1;
                int total = 0;
                for (int y = yl; y <= yr; ++y) {
                    total += distance(x, y);
                }
                tuple<int, int, int, int> current = {total, x, yl, yr};
                if (current < best) best = current;
            }
        }
    }

    if (get<0>(best) == INT_MAX) return {-1, -1, -1, -1};
    return best;
}

void mark_seats(int x, int yl, int yr) {
    auto& occupied = seats[x-1];
    pair<int, int> new_interval = {yl, yr};
    vector<pair<int, int>> temp;
    bool inserted = false;
    for (auto p : occupied) {
        if (p.first > new_interval.second + 1 && !inserted) {
            temp.push_back(new_interval);
            inserted = true;
        }
        if (p.second < new_interval.first -1) {
            temp.push_back(p);
        } else {
            new_interval.first = min(new_interval.first, p.first);
            new_interval.second = max(new_interval.second, p.second);
        }
    }
    if (!inserted) {
        temp.push_back(new_interval);
    }
    occupied.clear();
    for (auto p : temp) {
        occupied.insert(p);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N >> K;
    center_row = (K + 1) / 2;
    center_seat = (K + 1) / 2;

    seats.resize(K);

