};

map<string, Item> items;
map<string, Resident> residents;

vector<Item> possibleWeapons, possibleArmors, possibleOrbs;

int computeAtk(const Item &weapon) {
    int total = weapon.atk;
    for (const auto &rName : weapon.residents) {
        const Resident &r = residents[rName];
        if (r.type == "gladiator") total += r.bonus;
    }
    return total;
}

int computeDef(const Item &armor) {
    int total = armor.def;
    for (const auto &rName : armor.residents) {
        const Resident &r = residents[rName];
        if (r.type == "sentry") total += r.bonus;
    }
    return total;
}

int computeRes(const Item &orb) {
    int total = orb.res;
    for (const auto &rName : orb.residents) {
        const Resident &r = residents[rName];
        if (r.type == "physician") total += r.bonus;
    }
    return total;
}

void generateAllPossibleAssignments(vector<Item> &allItems, vector<Resident> &allResidents, vector<vector<Item>> &result, int index) {
    if (index == allResidents.size()) {
        result.push_back(allItems);
        return;
    }
    Resident &r = allResidents[index];
    for (auto &item : allItems) {
        if (item.residents.size() < item.size) {
            item.residents.push_back(r.name);
            generateAllPossibleAssignments(allItems, allResidents, result, index + 1);
            item.residents.pop_back();
        }
    }
}

