    vector<int> res;
    vector<int> nums;
    for (int i = 1; i <= m; ++i) nums.push_back(i);

    k--;
    for (int i = 0; i < m; ++i) {
        int idx = 0;
        while (k >= fact[m - i - 1]) {
            k -= fact[m - i - 1];
            idx++;
        }
        res.push_back(nums[idx]);
        nums.erase(nums.begin() + idx);
    }
    return res;
}

