#include <bits/stdc++.h>
using namespace std;

struct TrieNode {
    int cnt;
    unordered_map<char, TrieNode*> children;
    TrieNode() : cnt(0) {}
};

void insert(TrieNode* root, const string& s, int pos) {
    TrieNode* node = root;
    for (int i = pos; i < s.size(); ++i) {
        char c = s[i];
        if (node->children.find(c) == node->children.end()) {
            node->children[c] = new TrieNode();
        }
        node = node->children[c];
        node->cnt++;
    }
}

string findKth(TrieNode* root, int k) {
    string res;
    TrieNode* node = root;
    while (true) {
        if (k == 0) break;
        for (char c = 'a'; c <= 'z'; ++c) {
            if (node->children.find(c) != node->children.end()) {
                int child_cnt = node->children[c]->cnt;
                if (child_cnt >= k) {
                    res += c;
                    node = node->children[c];
                    k--;
                    break;
                } else {
                    k -= child_cnt;
                }
            }
        }
    }
    return res;
}

