    SuffixAutomaton(const string &s) {
        st.reserve(2 * s.size());
        st.emplace_back();
        last = 0;
        for (char c : s) extend(c);
    }

    void extend(char c) {
        int p = last;
        st.emplace_back();
        int curr = st.size() - 1;
        st[curr].len = st[p].len + 1;
        while (p != -1 && !st[p].next.count(c)) {
            st[p].next[c] = curr;
            p = st[p].link;
        }
        if (p == -1) {
            st[curr].link = 0;
        } else {
            int q = st[p].next[c];
            if (st[p].len + 1 == st[q].len) {
                st[curr].link = q;
            } else {
                int clone = st.size();
                st.push_back(st[q]);
                st[clone].len = st[p].len + 1;
                while (p != -1 && st[p].next[c] == q) {
                    st[p].next[c] = clone;
                    p = st[p].link;
                }
                st[q].link = clone;
                st[curr].link = clone;
            }
        }
        last = curr;
    }
};

