using namespace std;
typedef long long ll;
const ll MOD = 1e9+7;

ll choose(int a, int b) {
    if (a < b || b < 0) return 0;
    vector<ll> dp(a+1, 0);
    dp[0] = 1;
    for (int i = 1; i <= a; ++i) {
        for (int j = i; j >= 1; --j) {
            dp[j] = (dp[j] + dp[j-1]) % MOD;
        }
    }
    return dp[b];
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    if (2*k >= n || 2*k >= m) {
        cout << 0;
        return 0;
    }
    ll a = choose(n-2, 2*k);
    ll b = choose(m-2, 2*k);
    cout << (a * b) % MOD;
    return 0;
}

