#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MOD = 1e9+7;

ll comb(int n, int k) {
    if (k > n) return 0;
    vector<vector<ll>> C(n+1, vector<ll>(k+1, 0));
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= min(i, k); j++) {
            if (j == 0 || j == i) C[i][j] = 1;
            else C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
    }
    return C[n][k];
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    if (2*k >= n || 2*k >= m) {
        cout << 0 << endl;
        return 0;
    }

    ll a = comb(n-1, 2*k);
    ll b = comb(m-1, 2*k);
    cout << (a * b) % MOD << endl;
    return 0;
}

