    int sum = 0;
    while (n > 0) {
        sum += n % base;
        n /= base;
    }
    return sum;
}

int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    int A;
    cin >> A;
    int total = 0;
    for (int base = 2; base < A; base++) {
        total += sumDigits(A, base);
    }
    int denominator = A - 2;
    int common = gcd(total, denominator);
    cout << total/common << "/" << denominator/common;
    return 0;
}

