    vector<vector<int>> dp_masha(len, vector<int>(len, -1));
    vector<vector<int>> dp_petya(len, vector<int>(len, -1));

    function<int(int, int, bool)> play = [&](int l, int r, bool is_masha) {
        if (r - l == 1) {
            return (str[l] - '0') * 2 + (str[r] - '0');
        }
        if (is_masha && dp_masha[l][r] != -1) return dp_masha[l][r];
        if (!is_masha && dp_petya[l][r] != -1) return dp_petya[l][r];

        int res;
        if (is_masha) { 
            res = INT_MAX;
            for (int i = l; i <= r; ++i) {
                int next_l = l, next_r = r - 1;
                if (i == l) next_l++;
                else if (i == r) next_r = r - 1;
                else {
                    next_l = l;
                    next_r = r - 1;
                }
                int val = play(next_l, next_r, !is_masha);
                res = min(res, val);
            }
            dp_masha[l][r] = res;
