#include <cctype>
using namespace std;

bool isPunctuation(char c) {
    return c == '.' || c == ',' || c == '!' || c == '?';
}

int main() {
    string input;
    getline(cin, input);
    string output;
    bool prevIsLetter = false;
    bool prevIsPunct = false;

    for (size_t i = 0; i < input.size(); ++i) {
        char c = input[i];
        if (isalpha(c)) {
            if (prevIsPunct) {
                output += ' ';
                prevIsPunct = false;
            }
            output += c;
            prevIsLetter = true;
            prevIsPunct = false;
        } else if (isPunctuation(c)) {
            if (output.empty() || output.back() == ' ') {
                output.pop_back();
            }
            output += c;
            prevIsPunct = true;
            prevIsLetter = false;
        } else if (isspace(c)) {
            if (prevIsLetter) {
                bool nextIsPunctOrSpace = false;
                for (size_t j = i + 1; j < input.size(); ++j) {
                    if (isalpha(input[j])) {
                        nextIsPunctOrSpace = false;
                        break;
                    } else if (isspace(input[j])) {
                        continue;
                    } else if (isPunctuation(input[j])) {
                        nextIsPunctOrSpace = true;
                        break;
                    }
                }
                if (!nextIsPunctOrSpace) {
                    output += ' ';
                }
                prevIsLetter = false;
            }
            while (i + 1 < input.size() && isspace(input[i+1])) {
                i++;
            }
        }
    }

    if (!output.empty() && output.back() == ' ') {
        output.pop_back();
    }
    cout << output << endl;

    return 0;
}

