using namespace std;

double compute_time(int a, int d, double v) {
    double t_accel = v / a;
    double dist_accel = 0.5 * a * t_accel * t_accel;
    if (dist_accel >= d) {
        return sqrt(2.0 * d / a);
    } else {
        return t_accel + (d - dist_accel) / v;
    }
}

