    for (int i = 0; i < n; ++i) {
        int t_i, v_i;
        cin >> t_i >> v_i;

        double time_without_obstacle = t_i + compute_time(a, d, v_i);
        double earliest_possible = max(time_without_obstacle, prev_time);
