using namespace std;

// Determine the winner of a single round. Returns 0 for draw, 1 for a wins, 2 for b wins.
int judge(char a, char b) {
    if (a == b) return 0;
    if ((a == 'R' && b == 'S') || (a == 'S' && b == 'P') || (a == 'P' && b == 'R')) {
        return 1;
    }
    return 2;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string a, b;
    cin >> n >> a >> b;
    int m = a.size(), k = b.size();
    int total = m * k / __gcd(m, k); // LCM of m and k

    vector<pair<int, int>> cycle; // Stores the outcome of each round in one LCM cycle
    for (int i = 0; i < total; ++i) {
        char ca = a[i % m];
        char cb = b[i % k];
        int res = judge(ca, cb);
        cycle.push_back({res == 1 ? 0 : (res == 2 ? 1 : 0), res == 2 ? 1 : 0});
    }

    // Calculate the sum of each outcome in one cycle
    int cycle_a = 0, cycle_b = 0;
    for (auto &p : cycle) {
        cycle_a += p.first;
        cycle_b += p.second;
    }

    int full_cycles = n / total;
    int remainder = n % total;

    int total_a = full_cycles * cycle_a;
    int total_b = full_cycles * cycle_b;

    // Add the remainder rounds
    for (int i = 0; i < remainder; ++i) {
        total_a += cycle[i].first;
        total_b += cycle[i].second;
    }

    cout << total_a << " " << total_b << endl;

    return 0;
}

