    long long dx = 0, dy = 0;
    long long dx_min = 0, dx_max = 0;
    long long dy_min = 0, dy_max = 0;

    for (char c : s) {
        if (c == 'L') dx--;
        else if (c == 'R') dx++;
        else if (c == 'D') dy--;
        else if (c == 'U') dy++;

        dx_min = min(dx_min, dx);
