#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Range {
    long long min_x, max_x, min_y, max_y;
    Range() : min_x(0), max_x(0), min_y(0), max_y(0) {}
    Range(long long a, long long b, long long c, long long d) : min_x(a), max_x(b), min_y(c), max_y(d) {}
};

Range updateRange(const Range& current, const string& dir) {
    long long dx_min = 0, dx_max = 0, dy_min = 0, dy_max = 0;
    for (char c : dir) {
        switch(c) {
            case 'L': dx_min--; dx_max--; break;
            case 'R': dx_min++; dx_max++; break;
            case 'U': dy_min++; dy_max++; break;
            case 'D': dy_min--; dy_max--; break;
        }
    }
    dx_min = min(dx_min, dx_max);
    dx_max = max(dx_min, dx_max);
    dy_min = min(dy_min, dy_max);
    dy_max = max(dy_min, dy_max);

    long long new_min_x = current.min_x + dx_min;
    long long new_max_x = current.max_x + dx_max;
    long long new_min_y = current.min_y + dy_min;
    long long new_max_y = current.max_y + dy_max;

    return Range(new_min_x, new_max_x, new_min_y, new_max_y);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    Range current(0, 0, 0, 0);
    for (int i = 0; i < n; ++i) {
        string s;
