#include <iostream>
using namespace std;

typedef long long ll;

ll pow_mod(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp /= 2;
    }
    return result;
}

int main() {
    ll n, m;
    cin >> n >> m;
    if (n == 0) {
        cout << 0 % m << endl;
        return 0;
    }
    if (m == 1) {
        cout << 0 << endl;
        return 0;
    }
    ll res;
    if (n == 1) {
        res = 2 % m;
    } else {
        // Calculate (2^(n+2) - 2*n - 4) mod m
        ll pow_term = pow_mod(2, n + 2, m);
        ll sub_term = (2 * n + 4) % m;
        res = (pow_term - sub_term + m) % m;
    }
    cout << res << endl;
    return 0;
}

