#include <vector>
#include <algorithm>
using namespace std;

struct Dragon {
    int x;
    int y;
};

bool compare(Dragon a, Dragon b) {
    return a.x < b.x;
}

int main() {
    int s, n;
    cin >> s >> n;
    vector<Dragon> dragons(n);
    for(int i = 0; i < n; i++) {
        cin >> dragons[i].x >> dragons[i].y;
    }
    sort(dragons.begin(), dragons.end(), compare);
    bool possible = true;
    for(int i = 0; i < n; i++) {
        if(s > dragons[i].x) {
            s += dragons[i].y;
        } else {
            possible = false;
            break;
        }
    }
    cout << (possible ? "YES" : "NO") << endl;
    return 0;
}

