        int m = 2;
        while ((m * (m-1) * (m-2))/6 <= k) {
            m++;
        }
        m--;
        for (int i = 0; i < m; i++) {
            for (int j = i+1; j < m; j++) {
                graph[n+i][n+j] = 1;
                graph[n+j][n+i] = 1;
            }
        }
        k -= (m * (m-1) * (m-2))/6;
        n += m;
    }
    cout << n << endl;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cout << graph[i][j];
        }
        cout << endl;
    }
    return 0;
}

