using namespace std;

int main() {
    int k;
    cin >> k;
    vector<vector<int>> adj(100, vector<int>(100, 0));
    int n = 0;

    // Start with a complete graph of m nodes (clique) which has C(m,3) triangles
    // Then add nodes connected to two nodes in the clique to add triangles

    // Find the largest m where C(m,3) <= k
    int m = 0;
    while ((m+1)*(m)*(m-1)/6 <= k) {
        m++;
    }
    m--;

    for(int i=0; i<m; i++) {
        for(int j=i+1; j<m; j++) {
            adj[i][j] = 1;
            adj[j][i] = 1;
        }
    }
    int remaining = k - (m*(m-1)*(m-2)/6);
    n = m;

    // Now add additional nodes each connected to two nodes in the clique
    // Each new node connected to a pair in the clique adds (m-2) triangles
    // because the new node forms a triangle with every other node connected to the pair
    // Wait, no. If you connect a new node to two nodes in the clique, then the number of triangles added is (number of common neighbors of those two nodes)
    // For a clique, the two nodes have (m-2) common neighbors. So each such connection adds (m-2) triangles.
    // So for each new node connected to a pair (a, b), it adds (m-2) triangles.

    // So find how many pairs we need to connect, each contributing (m-2) triangles.

    // But since remaining can be up to (k - C(m,3)), which could be up to C(m+1,3) - C(m,3) -1, but perhaps m is as low as 0.

    if (m >= 3) {
        int add_per = m-2;
        while(remaining > 0) {
            // Find how many pairs we can connect with this add_per
            int possible = remaining / add_per;
            int max_pairs = (m*(m-1))/2;
            if (possible > max_pairs) possible = max_pairs;
            if (possible ==0) possible =1;

            // Connect a new node to a pair (a, b)
            // Find a pair that hasn't been used yet
            bool found = false;
            for(int a=0; a<m && !found; a++) {
                for(int b=a+1; b<m && !found; b++) {
                    if (adj[a][b] ==1) {
                        // Check if this pair hasn't been used yet for a new node
                        // Wait, the same pair can be used multiple times, each time adding (m-2) triangles
                        // So we can connect multiple nodes to the same pair (a, b)
                        // So no problem. So just connect the new node to a and b
                        adj[n][a] = 1;
                        adj[a][n] = 1;
                        adj[n][b] = 1;
                        adj[b][n] = 1;
                        n++;
                        remaining -= add_per;
                        found = true;
                        if (remaining <=0) break;
                    }
                }
            }
            if (!found) break;
        }
    }

    // If m was less than 3, handle differently. For example, k=1, m=3 gives 1 triangle. But if k=1, we can also create 3 nodes connected as a triangle.

    // Handle remaining for cases where m <3 (like k=1, m=3)
    if (m <3) {
        // Then the initial clique is 0, so need to build from scratch.
        // If k=1, create a triangle.
        if (k >=1) {
            adj[0][1] = adj[1][0] =1;
            adj[1][2] = adj[2][1] =1;
            adj[0][2] = adj[2][0] =1;
            n=3;
            remaining = k-1;
        }
        // Now for remaining, connect new nodes each connected to two nodes of the triangle, adding 1 triangle each.
        // Because each new node connected to two nodes of the triangle (which have 1 common neighbor) adds 1 triangle.
        while (remaining >0 && n <100) {
            adj[n][0] = adj[0][n] =1;
            adj[n][1] = adj[1][n] =1;
            remaining -=1;
            n++;
        }
    }

    // Now, output the adjacency matrix
    cout << n << endl;
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
