    for(int i=0; i<k; ++i) cin >> a[i];

    unordered_set<int> used(a.begin(), a.end());
    vector<vector<int>> res(k);

    // Assign each child's desired segment first
    for(int i=0; i<k; ++i) {
        res[i].push_back(a[i]);
    }

    // Fill the remaining segments for each child
    int current = 1;
    for(int child=0; child <k; ++child) {
        while(res[child].size() < n) {
            if(used.find(current) == used.end()) {
                res[child].push_back(current);
                used.insert(current);
            }
            current++;
        }
    }

    // Output the result
    for(auto &v : res) {
        for(int num : v) {
            cout << num << " ";
        }
        cout << endl;
    }

