        domain_end = s.find("ru", domain_end + 1);
    }

    string domain = s.substr(pos, domain_end - pos);
    string context = "";

    int remaining = s.length() - domain_end - 2;
    if (remaining > 0) {
        context = "/" + s.substr(domain_end + 2);
    } else if (remaining == 0 && s.substr(domain_end + 2).empty()) {
        context = "";
    }

