#include <iostream>
#include <string>

using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();

    // Determine protocol
    string protocol;
    if (s.substr(0, 3) == "htt") {
        protocol = "http";
    } else {
        protocol = "ftp";
    }
    int proto_len = protocol.size();

    // Find the domain and context
    int pos = proto_len;
    string domain, context;
    int min_domain_len = 1;

    // Look for ".ru" after protocol
    for (int i = proto_len; i <= n - 3; i++) {
        if (s.substr(i, 3) == "ru" && (i + 3 == n || s[i+3] != 'r')) {
            // Check if domain is at least 1 character
            if (i - proto_len >= min_domain_len) {
                domain = s.substr(proto_len, i - proto_len);
                pos = i + 3;
                // Check for context
                if (pos < n) {
                    context = s.substr(pos);
                }
                break;
            }
        }
    }

    // If not found (though problem says it's guaranteed)
    if (domain.empty()) {
        // Alternative approach: split after first possible .ru
        for (int i = proto_len; i <= n - 3; i++) {
            if (s.substr(i, 2) == "ru") { // maybe i+2 is the end
                if (i - proto_len >= 1) {
                    domain = s.substr(proto_len, i - proto_len);
                    pos = i + 2;
                    if (pos < n) {
                        context = s.substr(pos);
                    }
                    break;
                }
            }
        }
    }

    // Build the result
    string res = protocol + "://" + domain + ".ru";
    if (!context.empty()) {
        res += "/" + context;
    }

    cout << res << endl;
    return 0;
}

