vi inverse(vi q) {
    vi inv(q.size());
    for (int i = 0; i < q.size(); ++i) {
        inv[q[i]-1] = i+1;
    }
    return inv;
}

vi apply_inverse(vi p, vi q) {
    vi inv = inverse(q);
    return apply_permutation(p, inv);
}

