#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>

using namespace std;

const double PI = acos(-1.0);
const double EPS = 1e-9;

double to_degrees(double radians) {
    return radians * 180.0 / PI;
}

double normalize_angle(double angle) {
    angle = fmod(angle, 360.0);
    if (angle < 0) {
        angle += 360.0;
    }
    return angle;
}

int main() {
    int n;
    cin >> n;
    vector<double> angles;

    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;
        double angle = atan2(y, x);
        angles.push_back(normalize_angle(to_degrees(angle)));
    }

    sort(angles.begin(), angles.end());

    if (n == 1) {
        cout << fixed << setprecision(10) << 0.0 << endl;
        return 0;
    }

    double min_angle = 360.0;

    for (int i = 0; i < n; ++i) {
        double next_angle = angles[(i + 1) % n];
        double current_angle = angles[i];
        double diff = next_angle - current_angle;
        if (diff < -EPS) {
            diff += 360.0;
        }
        double gap = 360.0 - diff;
        if (gap < min_angle) {
            min_angle = gap;
        }
    }

    cout << fixed << setprecision(10) << 360.0 - min_angle << endl;

    return 0;
}

