#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

const double PI = acos(-1.0);
const double EPS = 1e-8;

struct Point {
    int x, y;
    double angle;
    Point(int x = 0, int y = 0) : x(x), y(y) {}
    void calcAngle() {
        angle = atan2(y, x) * 180.0 / PI;
        if (angle < -EPS) angle += 360.0;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Point> points(n);
    for (int i = 0; i < n; ++i) {
        cin >> points[i].x >> points[i].y;
        points[i].calcAngle();
    }

    sort(points.begin(), points.end(), [](const Point& a, const Point& b) {
        return a.angle < b.angle;
    });

    if (n == 1) {
        cout << fixed << setprecision(10) << 0.0 << endl;
        return 0;
    }

    double max_gap = 0.0;
    for (int i = 0; i < n; ++i) {
        double next_angle = points[(i + 1) % n].angle;
        if (next_angle < points[i].angle) next_angle += 360.0;
        max_gap = max(max_gap, next_angle - points[i].angle);
    }

    double min_angle = 360.0 - max_gap;
    if (min_angle < EPS) {
