#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> s(n);
    for(int i = 0; i < n; ++i) {
        double x;
        cin >> s[i] >> x;
    }

    vector<int> dp;
    for(int num : s) {
        auto it = upper_bound(dp.begin(), dp.end(), num);
        if(it == dp.end()) {
            dp.push_back(num);
        } else {
            *it = num;
        }
    }

    cout << n - dp.size() << endl;
}

