#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll INF = 1e18;

vector<int> primes;
vector<int> exponents;
ll best;

void generate_primes() {
    vector<bool> is_prime(100, true);
    for (int i = 2; i * i <= 100; ++i) {
        if (is_prime[i]) {
            for (int j = i * i; j <= 100; j += i) {
                is_prime[j] = false;
            }
        }
    }
    for (int i = 2; i <= 100; ++i) {
        if (is_prime[i]) {
            primes.push_back(i);
        }
    }
}

void backtrack(int pos, int max_exp, int remaining_divisors, ll current_number) {
    if (remaining_divisors == 1) {
        if (current_number < best) {
            best = current_number;
        }
        return;
    }
    if (pos >= primes.size()) return;
    if (current_number > best / primes[pos]) return;
    for (int e = 1; e <= max_exp; ++e) {
        if (remaining_divisors % (e + 1) == 0) {
            ll next_number = current_number;
            for (int k = 0; k < e; ++k) {
                next_number *= primes[pos];
                if (next_number > best) break;
            }
            if (next_number > best) break;
            exponents.push_back(e);
            backtrack(pos + 1, e, remaining_divisors / (e + 1), next_number);
            exponents.pop_back();
        }
    }
    backtrack(pos + 1, max_exp, remaining_divisors, current_number);
}

ll find_min_number(int n) {
    best = INF;
    exponents.clear();
    generate_primes();
    backtrack(0, 1000, n, 1);
    return best;
}

int main() {
    int n;
    cin >> n;
    cout << find_min_number(n) << endl;
    return 0;
}

