    primes.resize(60, 1);
    primes[0] = primes[1] = 0;
    for (int i=2; i*i<60; ++i) {
        if (primes[i]) {
            for (int j=i*i; j<60; j+=i) primes[j] = 0;
        }
    }
    for (int i=2; i<60; ++i) {
        if (primes[i]) prime_list.push_back(i);
    }
}

