    if (cur_div > n) return;
    if (cur_div == n) {
        if (cur_num < ans) ans = cur_num;
        return;
    }
    if (idx == prime_list.size()) return;
    int p = prime_list[idx];
    for (int e=1; e <= last_exp; ++e) {
        if (cur_num > ans / p) break;
        cur_num *= p;
        if (n % (cur_div * (e+1)) == 0) {
            dfs(idx+1, cur_num, cur_div*(e+1), e);
        }
    }
}

