        for (int j = 0; j < 3; ++j) {
            grid[i][j] = 1;
        }
    }

    // Apply each press
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            int times = presses[i][j];
            // Each press toggles the light and adjacent
            for (int t = 0; t < times; ++t) {
                // Toggle current
                grid[i][j] ^= 1;
                // Toggle up
                if (i > 0) grid[i-1][j] ^= 1;
                // Toggle down
                if (i < 2) grid[i+1][j] ^= 1;
                // Toggle left
                if (j > 0) grid[i][j-1] ^= 1;
                // Toggle right
                if (j < 2) grid[i][j+1] ^= 1;
            }
        }
    }

    // Output the result
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
