#include <vector>
#include <cmath>

using namespace std;

int countPrimitiveRoots(int p) {
    // Step 1: Find Euler's totient function of p-1, which for a prime p is p-1's factors
    // Since p is prime, φ(p-1) gives the number of primitive roots modulo p
    int n = p - 1;
    int result = n;

    // Find all prime factors of n using trial division
    vector<int> factors;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            while (n % i == 0) {
                n /= i;
            }
        }
    }
    if (n > 1) {
        factors.push_back(n);
    }

    // Compute Euler's totient function for the original n (which is p-1)
    n = p - 1;
    result = n;
    for (int prime : factors) {
        result = result / prime * (prime - 1);
    }

    return result;
}

int main() {
    int p;
    cin >> p;
    cout << countPrimitiveRoots(p) << endl;
    return 0;
}

