using namespace std;

bool isPrimitiveRoot(int p, int x) {
    if (x == 1) return false; // 1 can't be a primitive root

    int m = p - 1;
    for (int i = 2; i * i <= m; ++i) {
        if (m % i == 0) {
            bool check = true;
            long long pow_x = 1;
            for (int j = 0; j < m / i; ++j) {
                pow_x = (pow_x * x) % p;
            }
            if (pow_x == 1) return false;
            while (m % i == 0) m /= i;
        }
    }
    if (m > 1) {
        long long pow_x = 1;
        for (int j = 0; j < (p-1)/m; ++j) {
            pow_x = (pow_x * x) % p;
        }
        if (pow_x == 1) return false;
    }
    return true;
}

int countPrimitiveRoots(int p) {
    int result = 0;
    for (int x = 1; x < p; ++x) {
        if (isPrimitiveRoot(p, x)) {
            result++;
        }
    }
    return result;
}

