#include <iostream>
using namespace std;

bool isPrimitiveRoot(int p, int x) {
    int prod = 1;
    bool exists[p] = {false};
    for (int i = 1; i < p; ++i) {
        prod = (prod * x) % p;
        if (exists[prod]) return false;
        exists[prod] = true;
    }
    if (prod != 1) return false;
    for (int k = 1; k <= p-2; ++k) {
        if ((x-1) % p == 0) return false;
        int mod = 1;
        int exp = k;
        int base = x;
        while (exp > 0) {
            if (exp % 2 == 1) mod = (mod * base) % p;
            base = (base * base) % p;
            exp /= 2;
        }
        if ((mod - 1) % p == 0) return false;
    }
    return true;
}

int countPrimitiveRoots(int p) {
    int count = 0;
    for (int x = 1; x < p; ++x) {
        if (isPrimitiveRoot(p, x)) {
            ++count;
        }
    }
    return count;
}

int main() {
    int p;
    cin >> p;
    cout << countPrimitiveRoots(p) << endl;
    return 0;
}

