#include <string>
#include <vector>
using namespace std;

struct Point {
    int x, y;
};

Point parse(string s) {
    return {s[0] - 'a', s[1] - '1'};
}

vector<string> moves;

void move(int dx, int dy) {
    string m;
    if (dx > 0) m += "R";
    if (dx < 0) m += "L";
    if (dy > 0) m += "U";
    if (dy < 0) m += "D";
    moves.push_back(m);
}

int main() {
    string s_str, t_str;
    cin >> s_str >> t_str;
    Point s = parse(s_str);
    Point t = parse(t_str);
    int dx = t.x - s.x;
    int dy = t.y - s.y;

    int steps = max(abs(dx), abs(dy));
    cout << steps << endl;

    while (dx != 0 || dy != 0) {
        int step_x = 0, step_y = 0;
        if (dx > 0) { step_x = 1; dx--; }
        else if (dx < 0) { step_x = -1; dx++; }
        if (dy > 0) { step_y = 1; dy--; }
        else if (dy < 0) { step_y = -1; dy++; }
        move(step_x, step_y);
    }

    for (auto& m : moves) {
        cout << m << endl;
    }
    return 0;
}

