#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

struct Point {
    int x, y;
    Point(int x_, int y_) : x(x_), y(y_) {}
};

vector<string> moves;

void moveTowards(Point &current, const Point &target) {
    int dx = target.x - current.x;
    int dy = target.y - current.y;

    string move = "";
    if (dx > 0) {
        move += "R";
        current.x += 1;
    } else if (dx < 0) {
        move += "L";
        current.x -= 1;
    }

    if (dy > 0) {
        move += "U";
        current.y += 1;
    } else if (dy < 0) {
        move += "D";
        current.y -= 1;
    }

    if (!move.empty()) {
        moves.push_back(move);
    }
}

int main() {
    string s, t;
    cin >> s >> t;

    Point start(s[0] - 'a', s[1] - '1');
    Point end(t[0] - 'a', t[1] - '1');

    while (start.x != end.x || start.y != end.y) {
        moveTowards(start, end);
    }

    cout << moves.size() << endl;
    for (const string &m : moves) {
        cout << m << endl;
    }

    return 0;
}

