    Point move(char dir) {
        if (dir == 'L') return Point(x-1, y);
        if (dir == 'R') return Point(x+1, y);
        if (dir == 'U') return Point(x, y+1);
        if (dir == 'D') return Point(x, y-1);
        if (dir == 'LU') return Point(x-1, y+1);
        if (dir == 'LD') return Point(x-1, y-1);
        if (dir == 'RU') return Point(x+1, y+1);
        if (dir == 'RD') return Point(x+1, y-1);
