    teleporters.emplace_back(x1, y1, x2, y2);
}

bool is_corner(int x, int y) {
    return (x == 1 && y == 1) || (x == 1 && y == m) || (x == n && y == 1) || (x == n && y == m);
}

void construct_path() {
    path.emplace_back(1, 1);

    if (n % 2 == 0) {
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 1) {
                for (int j = 2; j <= m; j++) path.emplace_back(i, j);
            } else {
                for (int j = m; j >= 2; j--) path.emplace_back(i, j);
            }
        }
        for (int i = n; i >= 1; i--) {
            if (i % 2 == 0) {
                if (i == n) continue;
                for (int j = 2; j <= m; j++) path.emplace_back(i, j);
            } else {
                if (i == 1) continue;
                for (int j = m; j >= 2; j--) path.emplace_back(i, j);
            }
        }
    } else if (m % 2 == 0) {
        for (int j = 1; j <= m; j++) {
            if (j % 2 == 1) {
                for (int i = 2; i <= n; i++) path.emplace_back(i, j);
            } else {
                for (int i = n; i >= 2; i--) path.emplace_back(i, j);
            }
        }
        for (int j = m; j >= 1; j--) {
            if (j % 2 == 0) {
                if (j == m) continue;
                for (int i = 2; i <= n; i++) path.emplace_back(i, j);
            } else {
                if (j == 1) continue;
                for (int i = n; i >= 2; i--) path.emplace_back(i, j);
            }
        }
    } else {
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 1) {
                for (int j = 1; j <= m; j++) {
                    if (i == 1 && j == 1) continue;
                    path.emplace_back(i, j);
                }
            } else {
                for (int j = m; j >= 1; j--) {
                    if (i == 1 && j == 1) continue;
                    path.emplace_back(i, j);
                }
            }
        }
    }

    path.emplace_back(1, 1);
}

void handle_teleporters() {
    vector<pair<int, int>> broken_edges;
    for (size_t i = 0; i < path.size() - 1; ++i) {
        int x1 = path[i].first, y1 = path[i].second;
        int x2 = path[i+1].first, y2 = path[i+1].second;
        int dx = abs(x1 - x2), dy = abs(y1 - y2);
        if (dx + dy != 1) {
            broken_edges.emplace_back(i, i+1);
        }
    }

    for (auto &p : broken_edges) {
        int u = p.first, v = p.second;
        add_teleport(path[u].first, path[u].second, path[v].first, path[v].second);
    }
}

int main() {
