    for (int i = 0; i < n; ++i) {
        cin >> h[i];
    }

    int max_pos = max_element(h.begin(), h.end()) - h.begin();
    rotate(h.begin(), h.begin() + max_pos, h.end());

    vector<int> stack;
    long long result = 0;

    for (int i = 1; i < n; ++i) {
        while (!stack.empty() && h[i] > stack.back()) {
            stack.pop_back();
            result++;
        }
        if (stack.empty()) {
            stack.push_back(h[i]);
        } else {
            if (h[i] == stack.back()) {
                int cnt = count(stack.begin(), stack.end(), h[i]);
                result += cnt + (h[i] != h[0]);
            } else {
                result++;
            }
            stack.push_back(h[i]);
        }
    }

    while (stack.size() > 1) {
        int current = stack.back();
        stack.pop_back();
        if (current != stack.back()) {
            result++;
            break;
        }
    }

    cout << result << '\n';

