#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int n;
ll k;

string min_lex(string s) {
    string res = s;
    for (int i = 0; i < s.size(); i++) {
        rotate(s.begin(), s.begin()+1, s.end());
        if (s < res) res = s;
    }
    reverse(s.begin(), s.end());
    for (int i = 0; i < s.size(); i++) {
        rotate(s.begin(), s.begin()+1, s.end());
        if (s < res) res = s;
    }
    return res;
}

string min_rep(string s) {
    string res = s;
    for (auto &c : res) c ^= 1;
    return min(res, s);
}

bool is_canonical(const string &s) {
    string minimal = min_lex(s);
    string minimal_color = min_rep(minimal);
    return minimal_color == s;
}

map<string, bool> memo;

ll count_canonical(string s, int pos) {
    if (pos == n) {
        return is_canonical(s) ? 1 : 0;
    }
    string key = s.substr(0, pos);
    if (memo.count(key)) return memo[key];
    ll total = 0;
    s[pos] = '0';
    total += count_canonical(s, pos + 1);
    s[pos] = '1';
    total += count_canonical(s, pos + 1);
    return memo[key] = total;
}

string build(int pos, string &current, ll &k) {
    if (pos == n) {
        if (is_canonical(current) && --k == 0) {
            return current;
        }
        return "";
    }
    current[pos] = '0';
    memo.clear();
    ll cnt0 = count_canonical(current, pos);
    if (cnt0 >= k) {
        return build(pos + 1, current, k);
    } else {
        k -= cnt0;
        current[pos] = '1';
        return build(pos + 1, current, k);
    }
}

int main() {
    cin >> n >> k;
    string current(n, '0');
    memo.clear();
    ll total = count_canonical(current, 0);
    if (total < k) {
        cout << -1 << endl;
        return 0;
    }
    current = string(n, '0');
    string ans = build(0, current, k);
    cout << ans << endl;
    return 0;
}

