#include <iostream>
#include <vector>
#include <map>
#include <algorithm>
using namespace std;

map<vector<int>, int> memo;

int fact(int n) {
    int res = 1;
    for (int i = 2; i <= n; ++i) res *= i;
    return res;
}

int calculate_permutations(const vector<int>& counts) {
    int total = fact(6);
    for (int c : counts) total /= fact(c);
    return total;
}

vector<int> rotate_face(const vector<int>& cube, int f1, int f2, int f3, int f4) {
    vector<int> res = cube;
    res[f1] = cube[f2];
    res[f2] = cube[f3];
    res[f3] = cube[f4];
    res[f4] = cube[f1];
    return res;
}

vector<int> rotate(const vector<int>& cube, int type) {
    switch (type) {
        case 0: return rotate_face(cube, 0, 1, 5, 4); // front face clockwise
        case 1: return rotate_face(cube, 0, 4, 5, 1); // front face counter
        case 2: return rotate_face(cube, 0, 3, 5, 2); // right face clockwise
        case 3: return rotate_face(cube, 0, 2, 5, 3); // right counter
        case 4: return rotate_face(cube, 1, 2, 4, 3); // top clockwise
        case 5: return rotate_face(cube, 1, 3, 4, 2); // top counter
        default: return cube;
    }
}

vector<int> normalize(const vector<int>& cube) {
    vector<int> min_cube = cube;
    for (int i = 0; i < 6; ++i) {
        vector<int> rotated = cube;
        for (int j = 0; j < 4; ++j) {
            rotated = rotate_face(rotated, 0, 1, 5, 4);
            if (rotated < min_cube) min_cube = rotated;
        }
        rotated = cube;
        for (int j = 0; j < 4; ++j) {
            rotated = rotate_face(rotated, 0, 3, 5, 2);
            if (rotated < min_cube) min_cube = rotated;
        }
        rotated = cube;
        for (int j = 0; j < 4; ++j) {
            rotated = rotate_face(rotated, 1, 2, 4, 3);
            if (rotated < min_cube) min_cube = rotated;
        }
    }
    return min_cube;
}

int count_unique(const vector<int>& colors) {
    map<vector<int>, bool> visited;
    vector<vector<int>> stack;
    stack.push_back(colors);
    visited[normalize(colors)] = true;
    int count = 0;

    while (!stack.empty()) {
        vector<int> current = stack.back();
        stack.pop_back();
        count++;

        for (int i = 0; i < 6; ++i) {
            vector<int> next = rotate(current, i);
            vector<int> norm = normalize(next);
            if (!visited[norm]) {
                visited[norm] = true;
                stack.push_back(next);
            }
        }
    }
    return count;
}

int main() {
    string s;
    cin >> s;
    map<char, int> freq;
    for (char c : s) freq[c]++;
    vector<int> counts;
    for (auto& p : freq) counts.push_back(p.second);
