#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9 + 7;

int main() {
    int n;
    string s;
    int a[26];
    cin >> n >> s;
    for (int i = 0; i < 26; i++) {
        cin >> a[i];
    }

    vector<long long> dp(n + 1, 0);
    vector<int> max_len(n + 1, 0);
    vector<int> min_parts(n + 1, 1e9);

    dp[0] = 1;
    max_len[0] = 0;
    min_parts[0] = 0;

    for (int i = 1; i <= n; i++) {
        int current_max = 1e9;
        for (int j = i - 1; j >= 0; j--) {
            char c = s[j];
            current_max = min(current_max, a[c - 'a']);
            if (i - j > current_max) {
                break;
            }
            dp[i] = (dp[i] + dp[j]) % MOD;
            max_len[i] = max(max_len[i], max(max_len[j], i - j));
            min_parts[i] = min(min_parts[i], min_parts[j] + 1);
        }
    }

    cout << dp[n] << '\n';
    cout << max_len[n] << '\n';
    cout << min_parts[n] << '\n';

    return 0;
}

