using namespace std;
typedef long long ll;
const ll MOD = 1e9 + 7;
const int MAXN = 1e3 + 5;

int n;
string s;
int a[26];
ll dp[MAXN]; // dp[i] = number of ways for first i characters
int max_len[MAXN]; // max substring length up to i
int min_split[MAXN]; // min splits up to i

int main() {
    cin >> n >> s;
    for (int i = 0; i < 26; ++i) {
        cin >> a[i];
    }

    // Initialize DP arrays
    dp[0] = 1;
    max_len[0] = 0;
    min_split[0] = 0;

    for (int i = 1; i <= n; ++i) {
        max_len[i] = -1;
        min_split[i] = 1e9;
        int max_possible = a[s[i-1]-'a'];
        for (int j = i-1; j >= 0; --j) {
            int len = i - j;
            if (len > max_possible) break;
            // Update max possible length for current substring
            if (j > 0) {
                int prev_char = s[j-1] - 'a';
                max_possible = min(max_possible, a[prev_char]);
            }
            // Update dp[i]
            dp[i] = (dp[i] + dp[j]) % MOD;
            // Update max_len[i]
            if (max_len[j] != -1) {
                max_len[i] = max(max_len[i], max(len, max_len[j]));
            }
            // Update min_split[i]
            if (min_split[j] != 1e9) {
                min_split[i] = min(min_split[i], min_split[j] + 1);
            }
        }
        // Handle base case when j=0 (entire substring is from 0 to i)
        if (i <= max_possible) {
            max_len[i] = max(max_len[i], i);
            min_split[i] = min(min_split[i], 1);
        }
    }

    cout << dp[n] % MOD << "\n";
    cout << max_len[n] << "\n";
    cout << min_split[n] << "\n";

    return 0;
}

