#include <vector>
#include <algorithm>

using namespace std;

const int MAXN = 2e5 + 5;

vector<int> adj[MAXN];
int color[MAXN];
int maxColors = 0;

void dfs(int u, int parent) {
    int currentColor = 1;
    for (int v : adj[u]) {
        if (v == parent) continue;
        while (currentColor == color[u] || (parent != -1 && currentColor == color[parent])) {
            currentColor++;
        }
        color[v] = currentColor++;
        maxColors = max(maxColors, color[v]);
        dfs(v, u);
    }
}

