#include <algorithm>

using namespace std;

string generateName(int index) {
    string base = "A";
    base[0] += index % 26;
    if (index >= 26) base += to_string(index / 26);
    return base;
}

int main() {
    int n, k;
    cin >> n >> k;
    vector<string> s(n - k + 1);
    for (int i = 0; i < n - k + 1; ++i) {
        cin >> s[i];
    }

    vector<string> names(n);
    for (int i = 0; i < n; ++i) {
        names[i] = generateName(i);
    }

    for (int i = 0; i < s.size(); ++i) {
        if (s[i] == "NO") {
            int start = i;
            int end = i + k - 1;
            if (i == 0) {
                names[end] = names[start];
            } else {
                bool conflict = false;
                for (int j = start; j < end; ++j) {
                    if (names[j] == names[end]) {
                        conflict = true;
                        break;
                    }
                }
                if (!conflict) {
                    names[end] = names[start];
                } else {
                    for (int j = start + 1; j <= end; ++j) {
                        if (j - start >= 1) {
                            names[j] = names[start];
                            break;
                        }
                    }
                }
            }
        }
    }

