    cin >> n >> k;
    vector<string> s(n - k + 1);
    for (int i = 0; i < n - k + 1; ++i) {
        cin >> s[i];
    }

    vector<string> names(n);
    for (int i = 0; i < n; ++i) {
        names[i] = "A";
        names[i] += ('a' + i % 26);
    }

    for (int i = 0; i < n - k + 1; ++i) {
        if (s[i] == "YES") continue;
        // When the current window is "NO", there must be a duplicate in the window
        // Find a position to adjust to create a duplicate
        bool hasDup = false;
        for (int j = i; j < i + k; ++j) {
            for (int l = j + 1; l < i + k; ++l) {
                if (names[j] == names[l]) {
                    hasDup = true;
                    break;
                }
            }
            if (hasDup) break;
        }
        if (!hasDup) {
            // Need to create a duplicate. The easiest way is to set the last element in the window equal to the first
            names[i + k - 1] = names[i];
        }
    }

    for (auto& name : names) {
        name[0] = toupper(name[0]);
        for (size_t i = 1; i < name.size(); ++i) {
            name[i] = tolower(name[i]);
        }
        cout << name << " ";
    }
    cout << endl;

    return 0;
}

