    int candidate_p = round(mean);

    double poisson_ll = compute_poisson_log_likelihood(data, mean);
    double uniform_ll = compute_uniform_log_likelihood(data, candidate_p);

    if (poisson_ll > uniform_ll) {
        return "poisson";
    } else {
        return "uniform";
    }
}

