#include <cmath>
#include <algorithm>

using namespace std;

const double EPS = 1e-8;

double poisson_pmf(int k, double lambda) {
    return exp(-lambda + k * log(lambda) - lgamma(k + 1));
}

bool is_poisson(const vector<int>& samples) {
    double sum = 0;
    for (int x : samples) sum += x;
    double lambda = sum / samples.size();

    if (lambda <= EPS) return false;

    vector<int> counts(300, 0);
    int min_val = *min_element(samples.begin(), samples.end());
    for (int x : samples) {
        counts[x - min_val]++;
    }

    vector<double> expected;
    double total = samples.size();
    for (int i = 0; ; i++) {
        int val = min_val + i;
        double prob = poisson_pmf(val, lambda);
        if (prob * total < 0.5) break;
        expected.push_back(prob * total);
    }

    if (expected.size() < 3) return false;

    double chi2 = 0;
    int used_bins = 0;
    int current = 0;
    for (size_t i = 0; i < expected.size(); i++) {
        int observed = 0;
        while (current < 300 && (counts[current] == 0 || (i == 0 && current == 0))) {
            observed += counts[current];
            current++;
        }
        if (current >= 300) break;

        observed += counts[current];
        current++;
        double e = expected[i];
        if (e < 5) {
            if (i + 1 < expected.size()) {
                e += expected[i+1];
                observed += counts[current];
                current++;
                i++;
            }
        }
        if (e < EPS) continue;
        chi2 += pow(observed - e, 2) / e;
        used_bins++;
    }

    int df = used_bins - 2;
    if (df < 1) return false;

    return chi2 < 30.0;
}

bool is_uniform(const vector<int>& samples) {
    int min_val = *min_element(samples.begin(), samples.end());
    int max_val = *max_element(samples.begin(), samples.end());
    int range = max_val - min_val + 1;

    if (range > 1000) return false;

    vector<int> freq(range, 0);
    for (int x : samples) {
        freq[x - min_val]++;
    }

    int expected = samples.size() / range;
    if (expected < 5) return false;

    double chi2 = 0;
    for (int f : freq) {
        if (f == 0) continue;
        chi2 += pow(f - expected, 2) / expected;
    }

    int df = range - 1;
    return chi2 < 310.0;
}

int main() {
