        cin >> P >> N;

        vector<int> samples(N);
        for (int& x : samples) {
            cin >> x;
            x += P;
        }

        bool poisson = is_poisson(samples);
        bool uniform = is_uniform(samples);

        if (poisson && !uniform) {
            cout << "poisson\n";
        } else if (!poisson && uniform) {
            cout << "uniform\n";
        } else {
            if (samples.size() >= 20) {
                double mean = 0;
                for (int x : samples) mean += x;
                mean /= samples.size();

                double var = 0;
                for (int x : samples) var += (x - mean)*(x - mean);
                var /= samples.size() - 1;

                if (abs(var - mean) < 1.0) {
