#include <bits/stdc++.h>
using namespace std;

struct Voucher {
    int l, r, cost, duration;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x;
    cin >> n >> x;
    vector<Voucher> vouchers(n);
    for (int i = 0; i < n; ++i) {
        int l, r, cost;
        cin >> l >> r >> cost;
        vouchers[i] = {l, r, cost, r - l + 1};
    }

    unordered_map<int, vector<pair<int, int>>> durationMap;
    for (auto& voucher : vouchers) {
        durationMap[voucher.duration].push_back({voucher.r, voucher.cost});
    }

    for (auto& entry : durationMap) {
        sort(entry.second.begin(), entry.second.end());
        for (int i = 1; i < entry.second.size(); ++i) {
            entry.second[i].second = min(entry.second[i].second, entry.second[i-1].second);
        }
    }

    const int INF = 2e18;
    long long minCost = INF;

    for (auto& voucher : vouchers) {
        int needed = x - voucher.duration;
        if (needed < 0) continue;
        if (!durationMap.count(needed)) continue;

        auto& candidates = durationMap[needed];
        int left = 0, right = candidates.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (candidates[mid].first < voucher.l) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        if (left > 0) {
            minCost = min(minCost, (long long)voucher.cost + candidates[left-1].second);
        }
    }

    cout << (minCost == INF ? -1 : (int)minCost) << endl;

    return 0;
}

